    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "La résolution 04-2026-051, page 6, autorise la dérogation mineure 2026-0002 concernant le lot 6 658 131, avec une largeur avant sur la rue Maria de 30 mètres."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "La rubrique 8.4 et ses attendus, page 6, identifient la demande 2026-0005 au 3741 rue Principale et la résolution autorise la clôture de 1,52 mètre, malgré la discordance du numéro 2025-0005 dans le dispositif."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "La rubrique 10.1, page 7, désigne explicitement l’adoption du second projet de règlement 03-2026, dont les attendus précisent la modification du zonage dans la zone U-41."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "La résolution 2026-04-055, adoptée page 8, autorise expressément à enchérir et à acquérir des immeubles lors de la vente pour taxes du 11 juin 2026, ce qui constitue un acte foncier inclus."
    },
    {
      "item": "i07",
      "choice": "absent",
      "reason": "Cet item reprend exactement l’objet et l’étape de l’item i06 dans la même résolution, alors que la règle exclut le crédit d’un doublon de même type décrivant le même fait."
    }
  ]
